function e(r){return r.organization_name?.trim()||`Организация #${r.id}`}function i(r){return(r?.trim()||"O").substring(0,1).toUpperCase()}function a(r){if(!r)return"—";const n=new Date(r);return isNaN(n.getTime())?"—":new Intl.DateTimeFormat("ru-RU",{day:"2-digit",month:"long",year:"numeric"}).format(n)}function s(r){const n=Math.abs(r)%100,t=n%10;return n>10&&n<20?`${r} проектов`:t===1?`${r} проект`:t>=2&&t<=4?`${r} проекта`:`${r} проектов`}export{e as a,a as f,i as g,s as p};
